{
  "title": "Does the new checkout increase purchases?",
  "setting": "At Lantern Shop",
  "mission": "Decide whether the new checkout is ready to launch. Give {{product}} a **clear explanation of the evidence**.",
  "deadline": "Launch meeting in four days",
  "panels": [
    {
      "title": "Checkout test so far",
      "metrics": [
        {
          "label": "Current checkout",
          "value": "100 of 1,000 purchased",
          "note": "10% of visitors"
        },
        {
          "label": "New checkout",
          "value": "130 of 1,000 purchased",
          "note": "13% of visitors"
        },
        {
          "label": "Planned sample",
          "value": "1,800 visitors per version",
          "note": "Set before the test began"
        }
      ],
      "note": "Visitors were randomly assigned to a checkout version."
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "Helps plan and interpret experiments.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants to improve checkout without delaying the launch.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Checks calculations and assumptions when asked.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "evidence",
      "label": "Decision evidence",
      "start": 45,
      "goodWhen": "high"
    },
    {
      "id": "time",
      "label": "Launch time",
      "start": 80,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Difference or chance",
      "practice": "In one sentence, explain why a gap between two random groups might happen by chance."
    },
    {
      "id": "sample",
      "name": "Sample size",
      "practice": "For one comparison, write down the planned number of observations and why that number matters."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to a nontechnical colleague in two sentences, including one limit."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "The new checkout is ahead. Can we launch it now and use the meeting for something else?"
        },
        {
          "from": "data",
          "text": "A gap can appear just because different people landed in each group. We planned the sample before seeing these results."
        }
      ],
      "prompt": "What do you do with the early results?",
      "choices": [
        {
          "id": "rush",
          "text": "Discuss a launch based on the results we have now.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "We have fewer visitors than planned. The early gap may not hold up."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "time",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Check the planned sample before treating an early gap as a launch signal.",
              "example": "“We should reach the planned 1,800 visitors per version before making the call.”"
            }
          ],
          "next": "early"
        },
        {
          "id": "check-plan",
          "text": "Ask the AI to check the sample plan, then wait for it.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "With a 10% starting purchase rate, 1,800 visitors per version gives roughly an 80% chance of detecting a rise to 13%, using a common two-sided test. That is a planning estimate, not a guarantee."
            },
            {
              "from": "data",
              "text": "That fits our goal. Let's keep the planned stopping point."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 20
            },
            {
              "meter": "time",
              "change": -20
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "Planned sample reached",
              "metrics": [
                {
                  "label": "Current checkout",
                  "value": "180 of 1,800 purchased",
                  "note": "10% of visitors"
                },
                {
                  "label": "New checkout",
                  "value": "234 of 1,800 purchased",
                  "note": "13% of visitors"
                }
              ],
              "note": "The test stopped at its planned sample size."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You checked what the planned sample could reasonably detect before waiting for it.",
              "example": null
            }
          ],
          "next": "final"
        },
        {
          "id": "wait",
          "text": "Keep the test running to the planned sample size.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "That uses the time we have left, but I can wait for the meeting."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 10
            },
            {
              "meter": "time",
              "change": -20
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "Planned sample reached",
              "metrics": [
                {
                  "label": "Current checkout",
                  "value": "180 of 1,800 purchased",
                  "note": "10% of visitors"
                },
                {
                  "label": "New checkout",
                  "value": "234 of 1,800 purchased",
                  "note": "13% of visitors"
                }
              ],
              "note": "The test stopped at its planned sample size."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You kept the stopping point set before the results were visible.",
              "example": null
            },
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Check what size of difference the planned sample was meant to detect.",
              "example": "Ask {{ai}} to check the sample plan and its assumptions."
            }
          ],
          "next": "final"
        }
      ]
    },
    {
      "id": "early",
      "messages": [
        {
          "from": "product",
          "text": "Waiting costs us four days. Is the current gap enough to act on?"
        },
        {
          "from": "data",
          "text": "The test is still short of its planned size. We have not tested the early gap."
        }
      ],
      "prompt": "What do you recommend?",
      "choices": [
        {
          "id": "launch-early",
          "text": "Launch the new checkout using the early gap.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "We'll launch now, though we won't know whether the early lead will last."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -15
            },
            {
              "meter": "time",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Don't treat an untested early gap as evidence that the new checkout is better.",
              "example": "“Let's reach the planned sample and check how surprising the gap would be by chance.”"
            }
          ],
          "next": "early-launch"
        },
        {
          "id": "finish",
          "text": "Finish the planned test and check the final results.",
          "quality": "strong",
          "replies": [
            {
              "from": "data",
              "text": "That gives us the comparison we planned, though it means waiting for the meeting."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 20
            },
            {
              "meter": "time",
              "change": -20
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "Planned sample reached",
              "metrics": [
                {
                  "label": "Current checkout",
                  "value": "180 of 1,800 purchased",
                  "note": "10% of visitors"
                },
                {
                  "label": "New checkout",
                  "value": "234 of 1,800 purchased",
                  "note": "13% of visitors"
                }
              ],
              "note": "The test stopped at its planned sample size."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You accepted the delay to reach the planned sample before making the call.",
              "example": null
            }
          ],
          "next": "final"
        },
        {
          "id": "hold",
          "text": "Hold the launch without claiming the new checkout wins.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "We'll hold it for now, but we still need a plan for deciding."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 5
            },
            {
              "meter": "time",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Avoiding a premature launch is useful; also say how you will get enough evidence to decide.",
              "example": "“Let's continue to the planned 1,800 visitors per version.”"
            }
          ],
          "next": "held"
        }
      ]
    },
    {
      "id": "final",
      "messages": [
        {
          "from": "data",
          "text": "We can use a hypothesis test: it checks how surprising a gap this large would be if the two versions were equally likely to lead to a purchase."
        },
        {
          "from": "product",
          "text": "The new version is at 13% and the current one is at 10%. What should I tell the launch team?"
        }
      ],
      "prompt": "How do you make and explain the call?",
      "choices": [
        {
          "id": "claim",
          "text": "Recommend launch and say the test proves the gain will last.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "The gap looks promising, but this test cannot prove the exact gain will continue."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "time",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Separate the observed test result from a guarantee about future purchases.",
              "example": "“The new checkout did better in this test, but the future gain may differ.”"
            }
          ],
          "next": "overstated"
        },
        {
          "id": "check",
          "text": "Ask the AI to check the gap, then explain the result.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "Using a two-sided test, if the versions were equally likely to lead to a purchase, a gap at least this large in either direction would occur about 0.5% of the time. That calculation uses the planned final sample."
            },
            {
              "from": "data",
              "text": "The check supports a real difference, though it doesn't guarantee the size of the future gain."
            },
            {
              "from": "product",
              "text": "I can recommend launch with that limitation."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 25
            },
            {
              "meter": "time",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked how likely a gap this large would be if there were no real difference.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave the launch team a useful conclusion without promising a future result.",
              "example": "“The new checkout did better in the test, and chance alone is an unlikely explanation. The future gain may differ.”"
            }
          ],
          "next": "launched"
        },
        {
          "id": "defer",
          "text": "Hold the launch and ask for more data before checking.",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "We already reached the planned sample. Let's check it before deciding whether more data would help."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 0
            },
            {
              "meter": "time",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Check the planned result before requesting more data; waiting alone doesn't interpret the gap.",
              "example": "Ask {{ai}} to calculate how surprising the final gap would be if the versions were equally likely to lead to a purchase."
            }
          ],
          "next": "held"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "launched",
      "outcome": "The team launches the new checkout. In the test, purchases were 10% with the current version and 13% with the new one; the future gain is still uncertain."
    },
    {
      "id": "overstated",
      "outcome": "The team launches, but the claim that the gain will last goes beyond what the test can show. {{data}} asks for that claim to be corrected."
    },
    {
      "id": "early-launch",
      "outcome": "The team launches using the early 10% versus 13% gap. Because the test stopped short of its planned sample and the gap wasn't checked, the evidence for the decision is limited."
    },
    {
      "id": "held",
      "outcome": "The launch is held while the team decides what evidence it needs. No claim is made that the new checkout has won."
    }
  ],
  "summary": [
    "A gap between randomly assigned groups can happen by chance, so check the evidence before calling a winner.",
    "A sample plan sets a stopping point and estimates what size of difference a test can detect.",
    "Explain both what a test found and what it cannot guarantee."
  ]
}

{
  "title": "A luz vem em pacotes ou em ondas?",
  "setting": "Um laboratório imaginário",
  "mission": "Explore uma luz muito fraca e um átomo em um simulador. Descubra como a luz pode deixar **marcas separadas e formar um padrão de onda**.",
  "deadline": null,
  "panels": [
    {
      "title": "No simulador",
      "metrics": [
        {
          "label": "Tela",
          "value": "Duas fendas",
          "note": "A luz pode passar pelas fendas antes de chegar à tela."
        },
        {
          "label": "Átomo",
          "value": "Uma mudança disponível",
          "note": "Essa mudança precisa da energia de um pacote de luz vermelha."
        },
        {
          "label": "Luz azul",
          "value": "Pacote mais energético",
          "note": "Cada pacote azul tem mais energia que um pacote vermelho."
        }
      ],
      "note": "O simulador permite enviar um pacote de luz por vez."
    }
  ],
  "team": [
    {
      "id": "research",
      "role": "Pesquisadora",
      "expertise": "Ajuda a planejar testes e interpretar o que aparece na tela.",
      "ai": false
    },
    {
      "id": "tech",
      "role": "Técnico de laboratório",
      "expertise": "Prepara os aparelhos e quer experimentar possibilidades diferentes.",
      "ai": false
    }
  ],
  "meters": [],
  "skills": [
    {
      "id": "packets",
      "name": "Energia em pacotes",
      "practice": "Em uma frase, explique por que um pacote de luz pode servir para uma mudança no átomo e outro não."
    },
    {
      "id": "duality",
      "name": "Onda e partícula",
      "practice": "Desenhe uma tela com três marcas separadas e explique o que você esperaria ver depois de muitas marcas."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "research",
          "text": "Vamos enviar luz para a tela, um pacote por vez. Cada pacote de luz é chamado de fóton: é um exemplo de quantum, um pacote de energia."
        },
        {
          "from": "tech",
          "text": "Podemos deixar as duas fendas abertas ou ligar um aparelho que mostra por qual delas cada fóton passa."
        },
        {
          "from": "research",
          "text": "Quero descobrir se as marcas vão formar um padrão de onda. Como você começaria?"
        }
      ],
      "prompt": "Como você prepara a primeira observação?",
      "choices": [
        {
          "id": "paths",
          "text": "Ligo o aparelho para descobrir por qual fenda cada fóton passa.",
          "quality": "fair",
          "replies": [
            {
              "from": "tech",
              "text": "Depois de muitos fótons, vemos marcas separadas, mas não o padrão de listras. O aparelho nos contou por onde eles passaram."
            },
            {
              "from": "research",
              "text": "Descobrimos o caminho, mas essa observação mudou o resultado na tela. Para procurar as listras, podemos repetir sem o aparelho."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "improve",
              "text": "Saber o caminho é interessante, mas impede que esse teste mostre o padrão de onda. Experimente repetir sem medir o caminho.",
              "example": "“Vamos desligar o aparelho e comparar as marcas na tela.”"
            }
          ],
          "next": "measured"
        },
        {
          "id": "screen",
          "text": "Deixo as duas fendas abertas sem medir por qual delas a luz passa.",
          "quality": "strong",
          "replies": [
            {
              "from": "tech",
              "text": "Cada fóton deixa uma marca separada na tela. Depois de muitos, as marcas formam um padrão de listras."
            },
            {
              "from": "research",
              "text": "As marcas separadas lembram partículas; o padrão de listras lembra ondas. São dois comportamentos da mesma luz."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "good",
              "text": "Você observou tanto as marcas individuais quanto o padrão formado por muitas delas.",
              "example": null
            }
          ],
          "next": "unmeasured"
        }
      ]
    },
    {
      "id": "measured",
      "messages": [
        {
          "from": "tech",
          "text": "Agora o átomo está pronto no simulador. Há uma mudança disponível nele que precisa da energia de um pacote de luz vermelha."
        },
        {
          "from": "research",
          "text": "Vamos testar essa mudança antes de repetir a experiência das fendas. Um pacote azul tem energia demais para ela."
        }
      ],
      "prompt": "Qual pacote você envia ao átomo para tentar a mudança disponível?",
      "choices": [
        {
          "id": "blue",
          "text": "Envio um pacote azul para tentar provocar a mudança.",
          "quality": "weak",
          "replies": [
            {
              "from": "research",
              "text": "Neste teste, o átomo não absorve o pacote azul para essa mudança. Ele não pega só uma parte da energia do pacote."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "improve",
              "text": "Compare a energia do pacote com a energia necessária para a mudança disponível.",
              "example": "“Vou testar o pacote vermelho, que tem a energia certa para essa mudança.”"
            }
          ],
          "next": "blue-end"
        },
        {
          "id": "red",
          "text": "Envio um pacote vermelho para tentar provocar a mudança.",
          "quality": "strong",
          "replies": [
            {
              "from": "research",
              "text": "O átomo absorve o pacote vermelho e faz a mudança. Nesse átomo, essa mudança de energia também acontece em uma quantidade definida."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "good",
              "text": "Você escolheu um pacote com a energia certa para a mudança disponível no átomo.",
              "example": null
            }
          ],
          "next": "red-end"
        }
      ]
    },
    {
      "id": "unmeasured",
      "messages": [
        {
          "from": "tech",
          "text": "Agora o átomo está pronto no simulador. Há uma mudança disponível nele que precisa da energia de um pacote de luz vermelha."
        },
        {
          "from": "research",
          "text": "Já vimos marcas separadas formando listras. Vamos descobrir o que acontece quando um pacote de luz encontra o átomo."
        }
      ],
      "prompt": "Qual pacote você envia ao átomo para tentar a mudança disponível?",
      "choices": [
        {
          "id": "red",
          "text": "Envio um pacote vermelho para tentar provocar a mudança.",
          "quality": "strong",
          "replies": [
            {
              "from": "research",
              "text": "O átomo absorve o pacote vermelho e faz a mudança. Nesse átomo, essa mudança de energia também acontece em uma quantidade definida."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "good",
              "text": "Você escolheu um pacote com a energia certa para a mudança disponível no átomo.",
              "example": null
            }
          ],
          "next": "red-end"
        },
        {
          "id": "blue",
          "text": "Envio um pacote azul para tentar provocar a mudança.",
          "quality": "weak",
          "replies": [
            {
              "from": "research",
              "text": "Neste teste, o átomo não absorve o pacote azul para essa mudança. Ele não pega só uma parte da energia do pacote."
            }
          ],
          "effects": [],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "improve",
              "text": "Compare a energia do pacote com a energia necessária para a mudança disponível.",
              "example": "“Vou testar o pacote vermelho, que tem a energia certa para essa mudança.”"
            }
          ],
          "next": "blue-end"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "red-end",
      "outcome": "No simulador, o átomo absorveu o pacote vermelho e fez a mudança disponível. A energia do pacote combinava com a energia necessária para essa mudança."
    },
    {
      "id": "blue-end",
      "outcome": "No simulador, o átomo não absorveu o pacote azul para a mudança disponível. Você pode repetir o teste com o pacote vermelho e comparar."
    }
  ],
  "summary": [
    "Um fóton é um quantum de luz: um pacote de energia. Em um átomo, certas mudanças de energia também acontecem em quantidades definidas.",
    "A luz pode deixar marcas individuais como partículas e, em certas experiências, formar um padrão associado a ondas."
  ]
}

{
  "title": "Qual dose deve ser administrada?",
  "setting": "Plantão no Hospital Vale Sereno",
  "mission": "Confira a dose de cefazolina prescrita para uma criança de 18 kg e defina **como proceder antes da administração**.",
  "deadline": "Horário previsto da dose: 14h",
  "panels": [
    {
      "title": "Dados para a dose",
      "metrics": [
        {
          "label": "Peso registrado",
          "value": "18 kg",
          "note": "Peso atual confirmado no prontuário."
        },
        {
          "label": "Plano médico",
          "value": "10 mg/kg por dose",
          "note": "Cefazolina por via intravenosa."
        },
        {
          "label": "Prescrição atual",
          "value": "200 mg IV",
          "note": "Uma dose prevista para as 14h."
        },
        {
          "label": "Solução da farmácia",
          "value": "10 mg/mL",
          "note": "Preparada e identificada para uso intravenoso."
        }
      ],
      "note": "O plano médico e a prescrição precisam ser comparados antes da administração."
    }
  ],
  "team": [
    {
